from pathlib import Path
import sys
import unittest


PROJECT_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(PROJECT_ROOT / "src"))

from batch_processor import process_batch


class BatchProcessorTests(unittest.TestCase):
    def test_normalizes_string_items(self) -> None:
        self.assertEqual(
            [{"index": 0, "value": "alpha"}],
            process_batch([" Alpha "]),
        )

    def test_preserves_result_order(self) -> None:
        self.assertEqual(
            [
                {"index": 0, "value": "second"},
                {"index": 1, "value": "first"},
            ],
            process_batch(["second", "first"]),
        )

    def test_invalid_item_does_not_abort_neighbors(self) -> None:
        self.assertEqual(
            [
                {"index": 0, "value": "ok"},
                {"index": 1, "error": "item must be a string"},
                {"index": 2, "value": "still-ok"},
            ],
            process_batch(["ok", 3, "still-ok"]),
        )

    def test_accepts_fifty_items(self) -> None:
        self.assertEqual(50, len(process_batch(["item"] * 50)))

    def test_rejects_fifty_one_items_before_processing(self) -> None:
        with self.assertRaises(ValueError):
            process_batch([object()] * 51)


if __name__ == "__main__":
    unittest.main()

"""Process a request batch while preserving ordered per-item outcomes."""


def process_batch(items: list[object]) -> list[dict[str, object]]:
    if len(items) > 50:
        raise ValueError("batch cannot contain more than 50 items")

    results: list[dict[str, object]] = []
    for index, item in enumerate(items):
        if not isinstance(item, str):
            results.append({"index": index, "error": "item must be a string"})
            continue
        results.append({"index": index, "value": item.strip().lower()})
    return results

